"""Precomputed DA2 lookup tables, generated by tools/gen_da2_hashes.py.

Both tables ship as zlib-compressed marshal blobs instead of Python literals.
"""

from __future__ import annotations

import marshal
import zlib
from pathlib import Path

_DIR = Path(__file__).with_name("data")
_CACHE: dict[str, dict] = {}


def _load(name: str) -> dict:
    table = _CACHE.get(name)
    if table is None:
        try:
            # marshal is CPython-specific: regenerate the .bin files after a
            # Blender/Python upgrade (tools/gen_da2_hashes.py does the encode)
            table = marshal.loads(zlib.decompress((_DIR / name).read_bytes()))
        except (OSError, ValueError, EOFError, TypeError, zlib.error):
            table = {}
        if not isinstance(table, dict):
            table = {}
        _CACHE[name] = table
    return table


def type_exts() -> dict:
    # fnv32(lowercased extension) -> ".dds" and friends
    return _load("da2_type_exts.bin")


def names() -> dict:
    return _load("da2_names.bin")


def unload() -> None:
    # only needed while indexing; a finished scan must not keep ~340k entries
    _CACHE.clear()
